	capacity float64
	rate     float64
	tokens   float64
	last     time.Time
	clock    Clock
}

func NewLimiter(capacity int64, refillPerSec float64, initialTokens int64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("capacity must be > 0")
	}
	if refillPerSec <= 0 || math.IsNaN(refillPerSec) || math.IsInf(refillPerSec, 0) {
		return nil, fmt.Errorf("refill rate must be finite and > 0")
	}
	if initialTokens < 0 || initialTokens > capacity {
		return nil, fmt.Errorf("initial tokens must be in [0, capacity]")
	}
	if clock == nil {
		return nil, fmt.Errorf("clock must not be nil")
	}
	return &Limiter{
		capacity: float64(capacity),
		rate:     refillPerSec,
		tokens:   float64(initialTokens),
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = math.Min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}
